std::vector<std::pair<int, int>> generateSequence(int w, int h) {
    std::vector<std::pair<int, int>> sequence;
    int max_index = w * h;
    int x = 0, y = 0;
    int dx = 0, dy = -1;
    int t = 0;

    for (int i = 0; i < max_index; ++i) {
        if (-w/2 <= x && x <= w/2 && -h/2 <= y && y <= h/2) {
            sequence.push_back({x + w/2, y + h/2});
