</first_data>

<second_data>
import React from 'react';

function VisuallyHidden({ text, as = 'span', noTranslate = false, additionalAttributes = {} }: {
  text: string;
  as?: string;
  noTranslate?: boolean;
  additionalAttributes?: Record<string, any>;
}) {
  const attributes = {
    ...additionalAttributes,
    style: {
      position: 'absolute',
      width: '1px',
      height: '1px',
      padding: '0',
      margin: '0',
      overflow: 'hidden',
      clip: 'rect(0, 0, 0, 0)',
      border: '0',
    },
  };

  if (noTranslate) {
    attributes.style.whiteSpace = 'nowrap';
    attributes.style.overflow = 'hidden';
    attributes.style.textOverflow = 'ellipsis';
    attributes.style.display = 'block';
    attributes.style.maxWidth = '100%';
  }

  return <Tag {...attributes} className="visually-hidden" />;
}

export default VisuallyHidden;
</second_data>

