   ```json
   {
     "manifest_version": 2,
     "name": "API Text Sender",
     "version": "1.0",
     "description": "Sends selected text to an API and stores the result in the clipboard.",
     "permissions": [
       "activeTab",
       "contextMenus",
       "clipboardWrite"
     ],
     "background": {
       "scripts": ["background.js"],
       "persistent": false
     },
     "content_scripts": [
       {
         "matches": ["<all_urls>"],
         "js": ["content.js"]
       }
     ],
     "browser_action": {
