add_action( 'admin_notices', 'ts_admin_page_form' );
```

Step 6: Add the following code to the `text-splitter.php` file to create the function that splits the text into multiple posts:

```php
function ts_split_text() {
    // Check nonce
    if ( ! wp_verify_nonce( $_POST['ts_split_text_nonce'], 'ts_split_text' ) ) {
        die( 'Invalid nonce' );
    }

    // Check permissions
    if ( ! current_user_can( 'manage_options' ) ) {
        die( 'You do not have sufficient permissions to perform this action' );
    }

    // Get settings
    $word_count = get_option( 'ts_word_count' );

    // Get form data
    $title = sanitize_text_field( $_POST['ts_title'] );
    $text = wp_kses_post( $_POST['ts_text'] );

    // Split text into arrays
    $words = explode( ' ', $text );
    $posts = array_chunk( $words, $word_count );

    // Create posts
    $post_count = 1;
    foreach ( $posts as $post ) {
        $post_title = $title . ' ' . str_pad( $post_count, 3, '0', STR_PAD_LEFT );
        $post_content = implode( ' ', $post );

        // Create post
        $post_id = wp_insert_post(
            array(
                'post_title'   => $post_title,
                'post_content' => $post_content,
                'post_status'  => 'publish',
                'post_author'  => get_current_user_id(),
            )
        );

        // Increment post count
        $post_count++;
    }

    // Display success message
    echo '<div class="notice notice-success is-dismissible">';
    echo '<p>Text has been split into multiple posts.</p>';
    echo '</div>';
}
add_action( 'init', 'ts_split_text' );
