#include <stdio.h>
#include <stdlib.h>

int main() {
    char filename[FILENAME_MAX];
    FILE *file;
    int line_number = 1;
    int char_position = 0;
    int c;

    printf("Enter the filename of a text file: ");
    scanf("%s", filename);

    file = fopen(filename, "r");

    if (file == NULL) {
        fprintf(stderr, "Error: Unable to open file %s.\n", filename);
        exit(EXIT_FAILURE);
    }

    while ((c = fgetc(file)) != EOF) {
        if (c == '\n') {
            line_number++;
            char_position = 0;
        } else {
            char_position++;
